// ── Huvudingången ──────────────────────────────────────────────────────────

/**
 * Svara lokalt med årsreview-mönstret — eller null (då har hela kedjan
 * före redan lämnat null och API-flödet tar över som förr). Ligger efter
 * slutstenarna och FÖRE marknadsrytm i widgetens kedja och kan därför
 * aldrig stjäla en fråga från ett tidigare lager. Basens rapport-monster
 * äger «årsrapport»/«årsredovisning» (BOLAGETS rapport) — detta lager
 * äger PORTFÖLJENS vinkel: årsrapporteringen, reviewn, beslutsjournalen,
 * tur-eller-process-frågan (alla NULL genom kedjan före detta lager —
 * H-fallet bevisar). Samma matchningssemantik som basmotorn: minst ett
 * kärnord krävs, poäng = kärnord × 3 + stärkord, oavgjort → först
 * deklarerade mönstret vinner (strikt >, deterministiskt). Samma fråga
 * ⇒ bitidentiskt svar.
 */
export function svaraLokaltArsreview(fraga: string, register: RegisterRad[]): LokaltSvar | null {
  const fragaStr = diafri(fraga);
  if (!fragaStr) return null;
  const fragaOrd = fragaStr.split(" ");
  let bast: { svar: LokaltSvar; poang: number } | null = null;
  for (const m of ARSREVIEW_MONSTER) {
    const karnTraff = m.karnord.filter((nk) => traff(fragaOrd, fragaStr, nk));
    if (karnTraff.length === 0) continue; // krav: minst ett kärnord
    const starkTraff = m.starkord?.filter((nk) => traff(fragaOrd, fragaStr, nk)) ?? [];
    const poang = karnTraff.length * 3 + starkTraff.length;
    if (!bast || poang > bast.poang) bast = { svar: m.bygga(register), poang };
  }
  return bast ? bast.svar : null;
}
